	private void Configurations_Load(object sender, EventArgs e)
	{
		try
		{
			AutoScroll = true;
			base.AutoScrollMargin = new Size(10, 10);
			base.AutoScrollMinSize = new Size(1120, 800);
			SubsidiaryAccountAllownOnVouchers = CommonServices.GetERPFeatureById(4);
			chkInCasefSubsidiaryShowBothVendorAndCustomerOnSalesPurchase.Visible = SubsidiaryAccountAllownOnVouchers;
			label273.Visible = SubsidiaryAccountAllownOnVouchers;
			Party_ProcessingFeature = CommonServices.GetERPFeatureById(8);
			GBRegularWagesPartyProcessing.Visible = Party_ProcessingFeature;
			GBOtherWagesPartyProcessing.Visible = Party_ProcessingFeature;
			GBCommonWagesPartyProcessing.Visible = Party_ProcessingFeature;
			IncludeBankAccountsInFreightVoucherCreditAccount = Conversion.ToBool((object)GlobalVariables_Helper.GetConfigValueFromGlobal("IncludeBankAccountsInFreightVoucherCreditAccount"));
			BranchFeature = CommonServices.GetERPFeatureById(11);
			GbBranchWiseConfigPurchase.Visible = BranchFeature;
			GbBranchWiseConfigSale.Visible = BranchFeature;
			AccountBindFromGlobal();
			cmbCurrency();
			CityBindFromGlobal();
			WarehousesDtFillFromGlobalAndBind();
			PackingTypeDtFillFromGlobalAndBind();
			PaymentTermsFill();
			DeliveryTermFill();
			JobLotDtFillFromGlobalAndBind();
			GetWarehouseForPackingMaterial();
			CropDtFillFromGlobalAndBind();
			BudgetComboFill();
			TransportFill();
			GetRefDocumentsForWages();
			PartyGroupFill();
			BindCustomGroupAccounts();
			ItemCustomGroupFill();
			CastingType();
			BindForm();
			AssignEventHandlers(base.Controls);
			OriginAndInspectionCountryBind(CountryDtDbCall());
			ServiceItemNameBind();
			SupplierBind(SupplierDtFillFromGlobal());
			definition();
			CmbCustomGroupForWHTAccounts_Leave(null, null);
			CmbCustomGroupForWHTAccounts_Leave(null, null);
			TaxTypeBind(DatatableHelper.TaxTypesDbCall(UserAccount));
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

	private void TaxTypeBind(DataTable dt)
	{
		try
		{
			InfragisticsHelper.BindAndRetainSelection(CmbDefaultTaxTypePurchaseeIdForCommissionAgentPortal, dt, "Id", "TaxName", "Tax Name", AllColumns: true, Conversion.ToInt(CmbDefaultTaxTypePurchaseeIdForCommissionAgentPortal.Value), insertDefaultRow: false, null, null, ActivateRow: false);
			InfragisticsHelper.BindAndRetainSelection(CmbDefaultTaxTypeSaleIdForCommissionAgentPortal, dt, "Id", "TaxName", "Tax Name", AllColumns: true, Conversion.ToInt(CmbDefaultTaxTypeSaleIdForCommissionAgentPortal.Value), insertDefaultRow: false, null, null, ActivateRow: false);
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

	private void BindForm()
	{
		//IL_0000: Unknown result type (might be due to invalid IL or missing references)
		//IL_0005: Unknown result type (might be due to invalid IL or missing references)
		//IL_0016: Unknown result type (might be due to invalid IL or missing references)
		//IL_002c: Expected O, but got Unknown
		try
		{
			List<ConfigrationsAllocation> obj = ConfigrationsAllocation.HistoryConfiquration(new ConfigrationsAllocation
			{
				OrganizationId = UserAccount.OrganizationId,
				CompanyId = UserAccount.CompanyId
			});
			if (obj.Count <= 0)
			{
				return;
			}
			foreach (ConfigrationsAllocation configItem in obj)
			{
				Control control = FindControlByAccessibleName(this, configItem.ConfigDescription);
				if (control == null)
				{
					continue;
				}
				if (control is CheckBox checkBox)
				{
					checkBox.Checked = Conversion.ToBool((object)configItem.ConfigKey);
					continue;
				}
				if (control is TextBox textBox)
				{
					textBox.Text = configItem.ConfigKey;
					continue;
				}
				if (control is ComboBox comboBox)
				{
					comboBox.SelectedItem = configItem.ConfigKey;
					continue;
				}
				UltraCombo comb = (UltraCombo)(object)((control is UltraCombo) ? control : null);
				if (comb != null)
				{
					comb.Value = configItem.ConfigKey;
				}
				else
				{
					if (!(control is RadioButton radioButton))
					{
						continue;
					}
					if (radioButton.AccessibleName == "DaysForAdjacentHolidayAbsenceRule")
					{
						if (Conversion.ToInt((object)configItem.ConfigKey) == 0)
						{
							RadValueZero.Checked = true;
						}
						else if (Conversion.ToInt((object)configItem.ConfigKey) == 2)
						{
							radValueTwo.Checked = true;
						}
						else if (Conversion.ToInt((object)configItem.ConfigKey) == 3)
						{
							radValuethree.Checked = true;
						}
						continue;
					}
					if (radioButton.AccessibleName != "Lab Compulsory After First Weight" && radioButton.AccessibleName != "AutoRemarksIncludeChequeDateAndNumber" && radioButton.AccessibleName != "DefaulLedgerDetail" && radioButton.AccessibleName != "PackingMaterialCompulsoryOnStockConversionForWarning" && radioButton.AccessibleName != "CheckStockPartyItemWareHouse" && radioButton.AccessibleName != "CheckStockItemWareHouse")
					{
						radioButton.Checked = Conversion.ToBool((object)configItem.ConfigKey);
					}
					if (rdLabCompulsoryBeforFirstWeight.Checked)
					{
						rdLabCompulsoryAfterFirstWeight.Checked = false;
					}
					else
					{
						rdLabCompulsoryAfterFirstWeight.Checked = true;
					}
					if (rdAutoRemarksIncludeChequeDateAndNumber.Checked)
					{
						rdAutoRemarksIncludeChequeNumber.Checked = false;
					}
					else
					{
						rdAutoRemarksIncludeChequeNumber.Checked = true;
					}
					if (rdDetailLedger.Checked)
					{
						rdDefaulLedgerSummaryOne.Checked = false;
						rdDefaulLedgerSummaryTow.Checked = false;
					}
					else if (rdDefaulLedgerSummaryOne.Checked)
					{
						rdDetailLedger.Checked = false;
						rdDefaulLedgerSummaryTow.Checked = false;
					}
					else
					{
						rdDefaulLedgerSummaryTow.Checked = true;
					}
					if (Chk_IsMinusBlncAllow.Checked)
					{
						RadDisplayWarningforNegativeBalance.Checked = false;
						RadDisableBothNegativeBalanceRestrictions.Checked = false;
					}
					else if (RadDisplayWarningforNegativeBalance.Checked)
					{
						RadDisableBothNegativeBalanceRestrictions.Checked = false;
						Chk_IsMinusBlncAllow.Checked = false;
					}
					else
					{
						RadDisableBothNegativeBalanceRestrictions.Checked = true;
						Chk_IsMinusBlncAllow.Checked = false;
						RadDisplayWarningforNegativeBalance.Checked = false;
					}
					if (rdPackingMaterialCompulsoryOnStockConversionForWarning.Checked)
					{
						rdPackingMaterialCompulsoryOnStockConversionForStop.Checked = false;
					}
					else
					{
						rdPackingMaterialCompulsoryOnStockConversionForStop.Checked = true;
					}
					if (rdCheckStockPartyItemWareHouse.Checked)
					{
						rdCheckStockPartyItemWareHouseCropYear.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLot.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLotPackUom.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
					}
					else if (rdCheckStockPartyItemWareHouseCropYear.Checked)
					{
						rdCheckStockPartyItemWareHouse.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLot.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLotPackUom.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
					}
					else if (rdCheckStockPartyItemWareHouseCropYearJobLot.Checked)
					{
						rdCheckStockPartyItemWareHouse.Checked = false;
						rdCheckStockPartyItemWareHouseCropYear.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLotPackUom.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
					}
					else if (rdCheckStockPartyItemWareHouseCropYearJobLotPackUom.Checked)
					{
						rdCheckStockPartyItemWareHouse.Checked = false;
						rdCheckStockPartyItemWareHouseCropYear.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLot.Checked = false;
						rdCheckStockPartyItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
					}
					else
					{
						rdCheckStockPartyItemWareHouseCropYearJobLotPackingTypeUom.Checked = true;
					}
					if (rdItemWarehouse.Checked)
					{
						rdItemWarehouseCropYear.Checked = false;
						rdItemWarehouseCropYearJobLot.Checked = false;
						rdItemWarhouseCropJobPackUOM.Checked = false;
						rdCheckStockItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
					}
					else if (rdItemWarehouseCropYear.Checked)
					{
						rdItemWarehouse.Checked = false;
						rdItemWarehouseCropYearJobLot.Checked = false;
						rdItemWarhouseCropJobPackUOM.Checked = false;
						rdCheckStockItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
					}
					else if (rdItemWarehouseCropYearJobLot.Checked)
					{
						rdItemWarehouse.Checked = false;
						rdItemWarehouseCropYear.Checked = false;
						rdItemWarhouseCropJobPackUOM.Checked = false;
						rdCheckStockItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
					}
					else if (rdItemWarhouseCropJobPackUOM.Checked)
					{
						rdItemWarehouse.Checked = false;
						rdItemWarehouseCropYear.Checked = false;
						rdItemWarehouseCropYearJobLot.Checked = false;
						rdCheckStockItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
					}
					else
					{
						rdCheckStockItemWareHouseCropYearJobLotPackingTypeUom.Checked = true;
					}
					if (rdIsInspectionLotMappedOnDeliveryOrderByInvoice.Checked)
					{
						rdIsInspectionLotMappedOnDeliveryOrderByItem.Checked = false;
					}
					else
					{
						rdIsInspectionLotMappedOnDeliveryOrderByInvoice.Checked = false;
					}
					if (radGrnLoadingAllowDifferentBiltyDate.Checked)
					{
						radGrnLoadingDocDateAndBiltyDateNoValidation.Checked = false;
						radGrnLoadingDocDateAndBiltyDateSame.Checked = false;
					}
					else if (radGrnLoadingDocDateAndBiltyDateSame.Checked)
					{
						radGrnLoadingAllowDifferentBiltyDate.Checked = false;
						radGrnLoadingDocDateAndBiltyDateNoValidation.Checked = false;
					}
					else
					{
						radGrnLoadingAllowDifferentBiltyDate.Checked = false;
						radGrnLoadingDocDateAndBiltyDateSame.Checked = false;
					}
					if (radioButton.AccessibleName == "ShowWarningForLateVehicleArrivalAfterPoExpiryCommissionAgentPortal")
					{
						RadShowWarningForLateVehicleArrivalAfterPoExpiryCommissionAgentPortal.Checked = configItem.ConfigKey == "True";
					}
					else if (radioButton.AccessibleName == "BlockEntryForLateVehicleArrivalAfterPoExpiryCommissionAgentPortal")
					{
						RadBlockEntryForLateVehicleArrivalAfterPoExpiryCommissionAgentPortal.Checked = configItem.ConfigKey == "True";
					}
					if (!RadBlockEntryForLateVehicleArrivalAfterPoExpiryCommissionAgentPortal.Checked && !RadShowWarningForLateVehicleArrivalAfterPoExpiryCommissionAgentPortal.Checked)
					{
						RadNoValidationForLateVehicleArrivalAfterPoExpiryCommissionAgentPortal.Checked = true;
					}
				}
			}
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

	private Control FindControlByAccessibleName(Control parent, string accessibleName)
	{
		foreach (Control control in parent.Controls)
		{
			if (control.AccessibleName == accessibleName)
			{
				return control;
			}
			if (control.HasChildren)
			{
				Control foundControl = FindControlByAccessibleName(control, accessibleName);
				if (foundControl != null)
				{
					return foundControl;
				}
			}
		}
