	private void OriginAndInspectionCountryBind(DataTable dt)
	{
		try
		{
			int requestedById = Conversion.ToInt(CmbDefaultExportInspectionCountryOfOrigin.Value);
			if (dt.Rows.Count > 0)
			{
				DataTable dtOrigin = new DataTable();
				dtOrigin.Columns.Add("Id", typeof(int));
				dtOrigin.Columns.Add("Name", typeof(string));
				foreach (DataRow row in dt.Rows)
				{
					int id = Conversion.ToInt(row["Id"]);
					string name = Conversion.ToString(row["Description"]);
					dtOrigin.Rows.Add(id, name);
				}
				DDL.BindDDL(dtOrigin, CmbDefaultExportInspectionCountryOfOrigin, "Id", "Name", "Country Of Origin", ZeroIndex: true);
				CommonServices.SetComboValue(CmbDefaultExportInspectionCountryOfOrigin, "Id", requestedById, dtOrigin, ActivateRow: true, 1);
			}
			else
			{
				((UltraGridBase)CmbDefaultExportInspectionCountryOfOrigin).DataSource = null;
				((Control)(object)CmbDefaultExportInspectionCountryOfOrigin).Text = string.Empty;
			}
		}
		catch (Exception ex)
		{
			MessageBox.Show("Error binding lookup combos: " + ex.Message);
		}
	}

