	private void TransportFill()
	{
		try
		{
			int Id = Conversion.ToInt(CmbFreightOutwardAc.Value);
			DataTable dtSupplier = new DataTable();
			dtSupplier.Columns.Add("Id", typeof(int));
			dtSupplier.Columns.Add("AccountTitle");
			if (SubsidiaryAccountAllownOnVouchers)
			{
				DataTable dt = CommonServices.GetVendorsAndCustomersForTransporter();
				if (dt.Rows.Count > 0)
				{
					for (int i = 0; i < dt.Rows.Count; i++)
					{
						dtSupplier.Rows.Add(dt.Rows[i]["Id"], dt.Rows[i]["CompanyName"]);
					}
				}
			}
			else
			{
				DataTable dt2 = CommonServices.CoaAllocationGetAllServiceBind();
				if (dt2.Rows.Count > 0)
				{
					for (int j = 0; j < dt2.Rows.Count; j++)
					{
						if (Conversion.ToInt(dt2.Rows[j]["AccountTypeId"]) != 2 && Conversion.ToInt(dt2.Rows[j]["AccountTypeId"]) != 15 && Conversion.ToInt(dt2.Rows[j]["AccountTypeId"]) != 11)
						{
							dtSupplier.Rows.Add(dt2.Rows[j]["Id"], dt2.Rows[j]["AccountTitle"]);
						}
					}
				}
			}
			if (dtSupplier.Rows.Count > 0)
			{
				DDL.BindDDL(dtSupplier, CmbFreightOutwardAc, "Id", "AccountTitle", "Freight Outward", ZeroIndex: true);
				if (Id > 0)
				{
					if (dtSupplier.AsEnumerable().Any((DataRow row) => row.Field<int>("Id") == Id))
					{
						CmbFreightOutwardAc.Value = Id;
					}
					else
					{
						((Control)(object)CmbFreightOutwardAc).Text = string.Empty;
					}
				}
			}
			else
			{
				((Control)(object)CmbFreightOutwardAc).Text = string.Empty;
				((UltraGridBase)CmbFreightOutwardAc).DataSource = null;
			}
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

