			if (dt.Rows.Count > 0)
			{
				DataTable dtWages = new DataTable();
				dtWages.Columns.Add("Id", typeof(int));
				dtWages.Columns.Add("RefDocumentTypeId", typeof(int));
				dtWages.Columns.Add("DocumentTypeDescription", typeof(string));
