			{
				return;
			}
			ConfigrationsAllocation CA = new ConfigrationsAllocation();
			ConfigrationsAllocation chk = ConfigrationsAllocation.GetByKey(cmbBox.AccessibleName, UserAccount.OrganizationId, UserAccount.CompanyId);
			if (chk == null)
			{
				int ConfigurationId = ActivityLog.ReadByConfigDescription(cmbBox.AccessibleName);
				if (ConfigurationId == 0)
				{
					MessageBox.Show("Configuration Not Found");
					return;
				}
				CA.Id = 0;
				CA.ConfigrationsDefinitionId = ConfigurationId;
			}
			else
			{
				CA.Id = chk.Id;
				CA.ConfigrationsDefinitionId = chk.ConfigrationsDefinitionId;
			}
			CA.ConfigDescription = cmbBox.AccessibleName;
			CA.ConfigValue = "";
			CA.ConfigKey = cmbBox.SelectedValue.ToString();
			CA.IsActive = true;
			CA.OrganizationId = UserAccount.OrganizationId;
			CA.CompanyId = UserAccount.CompanyId;
			CA.EntryUserId = UserAccount.ID;
			CA.ModifyUserId = UserAccount.ID;
			ConfigrationsAllocation.Save(CA);
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

