	private void ControlEventHandler(object sender, EventArgs e)
	{
		try
		{
			Control control = sender as Control;
			if (control is CheckBox checkBox)
			{
				Fire(checkBox);
				if (checkBox.AccessibleName == "AutoRemarksForPaymentThroughBank")
				{
					if (chkAutoRemarksForPaymentThroughBank.Checked)
					{
						GroupBoxAutoRemarks.Enabled = true;
					}
					else
					{
						GroupBoxAutoRemarks.Enabled = false;
					}
				}
				if (checkBox.AccessibleName == "IncludeBankAccountsInFreightVoucherCreditAccount")
				{
					CmbDefaultFreightVoucherCreditAccountFillFromGlobal();
				}
				if (checkBox.AccessibleName == "IsGdnFirstFlow")
				{
					if (!chkIsGdnFirstFlow.Checked && chkRequireSaleInvoiceBeforeGatePass_GDNFirstFlow.Checked)
					{
						chkRequireSaleInvoiceBeforeGatePass_GDNFirstFlow.Checked = false;
						Fire(chkRequireSaleInvoiceBeforeGatePass_GDNFirstFlow);
					}
					CmbDefaultFreightVoucherCreditAccountFillFromGlobal();
				}
				return;
			}
			if (control is RadioButton radioButton)
			{
				if (!string.IsNullOrEmpty(radioButton.AccessibleName))
				{
					if (radioButton.AccessibleName == "DaysForAdjacentHolidayAbsenceRule")
					{
						TextBox textBox = new TextBox();
						if (RadValueZero.Checked)
						{
							textBox.Name = RadValueZero.Name;
							textBox.AccessibleName = RadValueZero.AccessibleName;
							textBox.Text = "0";
						}
						else if (radValueTwo.Checked)
						{
							textBox.Name = radValueTwo.Name;
							textBox.AccessibleName = radValueTwo.AccessibleName;
							textBox.Text = "2";
						}
						else if (radValuethree.Checked)
						{
							textBox.Name = radValuethree.Name;
							textBox.AccessibleName = radValuethree.AccessibleName;
							textBox.Text = "3";
						}
						FireTextBox(textBox);
						return;
					}
					if (base.ActiveControl != null && (base.ActiveControl.Name == "rdLabCompulsoryAfterFirstWeight" || base.ActiveControl.Name == "rdLabCompulsoryBeforFirstWeight"))
					{
						if (rdLabCompulsoryBeforFirstWeight.Checked)
						{
							rdLabCompulsoryAfterFirstWeight.Checked = false;
							FireRadioButton(rdLabCompulsoryAfterFirstWeight);
						}
						else
						{
							rdLabCompulsoryBeforFirstWeight.Checked = false;
							FireRadioButton(rdLabCompulsoryBeforFirstWeight);
						}
					}
					if (base.ActiveControl != null && (base.ActiveControl.Name == "rdAutoRemarksIncludeChequeDateAndNumber" || base.ActiveControl.Name == "rdAutoRemarksIncludeChequeNumber"))
					{
						if (rdAutoRemarksIncludeChequeDateAndNumber.Checked)
						{
							rdAutoRemarksIncludeChequeNumber.Checked = false;
							FireRadioButton(rdAutoRemarksIncludeChequeNumber);
						}
						else
						{
							rdAutoRemarksIncludeChequeDateAndNumber.Checked = false;
							FireRadioButton(rdAutoRemarksIncludeChequeDateAndNumber);
						}
					}
					if (base.ActiveControl != null && (base.ActiveControl.Name == "rdDetailLedger" || base.ActiveControl.Name == "rdDefaulLedgerSummaryOne" || base.ActiveControl.Name == "rdDefaulLedgerSummaryTow"))
					{
						if (rdDetailLedger.Checked)
						{
							rdDefaulLedgerSummaryOne.Checked = false;
							rdDefaulLedgerSummaryTow.Checked = false;
							FireRadioButton(rdDefaulLedgerSummaryOne);
							FireRadioButton(rdDefaulLedgerSummaryTow);
						}
						else if (rdDefaulLedgerSummaryOne.Checked)
						{
							rdDetailLedger.Checked = false;
							rdDefaulLedgerSummaryTow.Checked = false;
							FireRadioButton(rdDetailLedger);
							FireRadioButton(rdDefaulLedgerSummaryTow);
						}
						else
						{
							rdDetailLedger.Checked = false;
							rdDefaulLedgerSummaryOne.Checked = false;
							FireRadioButton(rdDetailLedger);
							FireRadioButton(rdDefaulLedgerSummaryOne);
						}
					}
					if (base.ActiveControl != null && (base.ActiveControl.Name == "rdPackingMaterialCompulsoryOnStockConversionForWarning" || base.ActiveControl.Name == "rdPackingMaterialCompulsoryOnStockConversionForStop"))
					{
						if (rdPackingMaterialCompulsoryOnStockConversionForWarning.Checked)
						{
							rdPackingMaterialCompulsoryOnStockConversionForStop.Checked = false;
							FireRadioButton(rdPackingMaterialCompulsoryOnStockConversionForStop);
						}
						else
						{
							rdPackingMaterialCompulsoryOnStockConversionForWarning.Checked = false;
							FireRadioButton(rdPackingMaterialCompulsoryOnStockConversionForWarning);
						}
					}
					if (base.ActiveControl != null && (base.ActiveControl.Name == "Chk_IsMinusBlncAllow" || base.ActiveControl.Name == "RadDisplayWarningforNegativeBalance" || base.ActiveControl.Name == "RadDisableBothNegativeBalanceRestrictions"))
					{
						if (Chk_IsMinusBlncAllow.Checked)
						{
							RadDisplayWarningforNegativeBalance.Checked = false;
							RadDisableBothNegativeBalanceRestrictions.Checked = false;
							FireRadioButton(RadDisplayWarningforNegativeBalance);
							FireRadioButton(RadDisableBothNegativeBalanceRestrictions);
						}
						else if (RadDisplayWarningforNegativeBalance.Checked)
						{
							Chk_IsMinusBlncAllow.Checked = false;
							RadDisableBothNegativeBalanceRestrictions.Checked = false;
							FireRadioButton(Chk_IsMinusBlncAllow);
							FireRadioButton(RadDisableBothNegativeBalanceRestrictions);
						}
						else
						{
							Chk_IsMinusBlncAllow.Checked = false;
							RadDisplayWarningforNegativeBalance.Checked = false;
							FireRadioButton(Chk_IsMinusBlncAllow);
							FireRadioButton(RadDisplayWarningforNegativeBalance);
						}
					}
					if (base.ActiveControl != null && (base.ActiveControl.Name == "rdCheckStockPartyItemWareHouse" || base.ActiveControl.Name == "rdCheckStockPartyItemWareHouseCropYear" || base.ActiveControl.Name == "rdCheckStockPartyItemWareHouseCropYearJobLot" || base.ActiveControl.Name == "rdCheckStockPartyItemWareHouseCropYearJobLotPackUom" || base.ActiveControl.Name == "rdCheckStockPartyItemWareHouseCropYearJobLotPackingTypeUom"))
					{
						if (rdCheckStockPartyItemWareHouse.Checked)
						{
							rdCheckStockPartyItemWareHouseCropYear.Checked = false;
							rdCheckStockPartyItemWareHouseCropYearJobLot.Checked = false;
							rdCheckStockPartyItemWareHouseCropYearJobLotPackUom.Checked = false;
							rdCheckStockPartyItemWareHouseCropYearJobLotPackingTypeUom.Checked = false;
							FireRadioButton(rdCheckStockPartyItemWareHouseCropYear);
