				}
				else if (((Control)(object)comboBox).AccessibleName == "CustomGroupForWHTAccountsSale")
				{
					CmbCustomGroupForWHTAccountsSale_Leave(null, null);
				}
			}
			else if (control is ComboBox comb)
			{
				FireDDL(comb);
			}
			else if (control is DateTimePicker dateTimePicker)
			{
				FireDateTime(dateTimePicker);
			}
			else
			{
				if (!(control is TextBox textBox2))
				{
					return;
				}
				if (textBox2.AccessibleName == "ToleranceForInPutMinusOutputForConversionInPercent")
				{
					double min = Conversion.ToDouble((object)txtMinPercentForStockConversion.Text);
					double max = Conversion.ToDouble((object)txtMaxPercentForStockConversion.Text);
					double Final = Conversion.ToDouble((object)txtToleranceForInPutMinusOutputForConversionInPercent.Text);
					if (!(Final >= min) || !(Final <= max))
					{
						if (Final < min)
						{
							txtToleranceForInPutMinusOutputForConversionInPercent.Text = min.ToString();
							txtToleranceForInPutMinusOutputForConversionInPercent.Focus();
							MessageBox.Show("tolerence % Can't less than Min %", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							return;
						}
						if (Final > max)
						{
							txtToleranceForInPutMinusOutputForConversionInPercent.Text = max.ToString();
							txtToleranceForInPutMinusOutputForConversionInPercent.Focus();
							MessageBox.Show("tolerence % Can't Greater than Max %", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							return;
						}
					}
					FireTextBox(textBox2);
				}
				else if (textBox2.AccessibleName == "LossWeightTolerancePercentageForProduction")
				{
					double min2 = Conversion.ToDouble((object)txtMinLossForProduction.Text);
					double max2 = Conversion.ToDouble((object)txtMaxLossForProduction.Text);
					double Final2 = Conversion.ToDouble((object)txtLossWeightTolerancePercentageForProduction.Text);
					if (!(Final2 >= min2) || !(Final2 <= max2))
					{
						if (Final2 < min2)
						{
							txtLossWeightTolerancePercentageForProduction.Text = min2.ToString();
							txtLossWeightTolerancePercentageForProduction.Focus();
							MessageBox.Show("tolerence % Can't less than Min %", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							return;
						}
						if (Final2 > max2)
						{
							txtLossWeightTolerancePercentageForProduction.Text = max2.ToString();
							txtLossWeightTolerancePercentageForProduction.Focus();
							MessageBox.Show("tolerence % Can't Greater than Max %", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							return;
						}
					}
					FireTextBox(textBox2);
				}
				else if (textBox2.AccessibleName == "GainWeightTolerancePercentageForProduction")
				{
					double min3 = Conversion.ToDouble((object)txtMinForGainProduction.Text);
					double max3 = Conversion.ToDouble((object)txtMaxForGainProduction.Text);
					double Final3 = Conversion.ToDouble((object)txtGainWeightTolerancePercentageForProduction.Text);
					if (!(Final3 >= min3) || !(Final3 <= max3))
					{
						if (Final3 < min3)
						{
							txtGainWeightTolerancePercentageForProduction.Text = min3.ToString();
							txtGainWeightTolerancePercentageForProduction.Focus();
							MessageBox.Show("tolerence % Can't less than Min %", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							return;
						}
						if (Final3 > max3)
						{
							txtGainWeightTolerancePercentageForProduction.Text = max3.ToString();
							txtGainWeightTolerancePercentageForProduction.Focus();
							MessageBox.Show("tolerence % Can't Greater than Max %", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
							return;
						}
					}
					FireTextBox(textBox2);
				}
				else if (textBox2.AccessibleName == "PartyProcessingGdnGrossWeightAndFactoryWeightDifferenceTolerance")
				{
					if (Conversion.ToDecimal((object)txtPartyProcessingGdnGrossWeightAndFactoryWeightDifferenceTolerance.Text) > 50m)
					{
						txtPartyProcessingGdnGrossWeightAndFactoryWeightDifferenceTolerance.Text = 50.ToString();
						txtPartyProcessingGdnGrossWeightAndFactoryWeightDifferenceTolerance.Focus();
						MessageBox.Show("tolerence Can't Greater than 30 KG", "Warning", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
					}
					else
					{
						FireTextBox(textBox2);
					}
				}
				else
				{
					FireTextBox(textBox2);
				}
			}
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Hand);
		}
	}

	private void AssignEventHandlers(Control.ControlCollection controls)
	{
		foreach (Control control in controls)
		{
			if (control is CheckBox || control is RadioButton)
			{
				control.Click += ControlEventHandler;
			}
			else if (control is TextBox)
			{
				control.Leave += ControlEventHandler;
				if (Conversion.ToString(control.Tag) == "KeyPressDecimalOnly")
				{
					control.KeyPress += Decimal_KeyPress;
				}
				if (Conversion.ToString(control.Tag) == "KeyPressNumberOnly")
				{
					control.KeyPress += Numbers_KeyPress;
				}
			}
			else if (control is DateTimePicker dateTimePicker)
			{
				dateTimePicker.ValueChanged += ControlEventHandler;
			}
			else if (control is UltraCombo)
			{
				control.Leave += ControlEventHandler;
			}
			if (control.HasChildren)
			{
				AssignEventHandlers(control.Controls);
			}
		}
	}

