	private void btnStatusUpdate_Click(object sender, EventArgs e)
	{
		//IL_002e: Unknown result type (might be due to invalid IL or missing references)
		//IL_0034: Expected O, but got Unknown
		//IL_0056: Unknown result type (might be due to invalid IL or missing references)
		//IL_005d: Expected O, but got Unknown
		try
		{
			if (grdWagesRefDocuments.GetRows().Count() > 0 && MessageBox.Show("Are you sure to Update Status?", "Confirm", MessageBoxButtons.YesNo) != DialogResult.No)
			{
				ApprovalList obj = new ApprovalList();
				obj.AllApprovalLists = new List<ApprovalList>();
				GridEXRow[] dataRows = grdWagesRefDocuments.GetDataRows();
				foreach (GridEXRow r in dataRows)
				{
					ApprovalList item = new ApprovalList();
					item.OrganizationId = UserAccount.OrganizationId;
					item.CompanyId = UserAccount.CompanyId;
					item.DocumentTypeId = Conversion.ToInt(r.Cells["RefDocumentTypeId"].Value);
					item.Id = Conversion.ToInt(r.Cells["Id"].Value);
					item.PostDate = DateTime.Now;
					item.EntryUser = UserAccount.ID;
					item.Status = Conversion.ToBool(r.Cells["IsActive"].Value);
					obj.AllApprovalLists.Add(item);
				}
				InvContractorWagesBillHeader.UpdateContractorWagesRefDocumentStatus(obj);
				MessageBox.Show("Record's Status Updated Successfully");
				GetRefDocumentsForWages();
			}
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

