	private void CmbCustomGroupForWHTAccounts_Leave(object sender, EventArgs e)
	{
		try
		{
			int Id = Conversion.ToInt(CmbCustomGroupForWHTAccounts.Value);
			if (Id > 0)
			{
				DataTable dtForPurchase = DatatableHelper.GetAccountsFromGlobalByTypeIds(null, null, null, null, null, null, null, new int[1] { Id });
				InfragisticsHelper.BindAndRetainSelection(CmbDefaultWhtAccountPurchaseIdForCommissionAgentPortal, dtForPurchase, "Id", "AccountTitle", "WHT Credit Account", AllColumns: true, Conversion.ToInt(CmbDefaultWhtAccountPurchaseIdForCommissionAgentPortal.Value), insertDefaultRow: false, null, null, ActivateRow: false);
			}
			else
			{
				((UltraGridBase)CmbDefaultWhtAccountPurchaseIdForCommissionAgentPortal).DataSource = null;
				((Control)(object)CmbDefaultWhtAccountPurchaseIdForCommissionAgentPortal).Text = "";
			}
		}
		catch (Exception ex)
		{
			MessageBox.Show(ex.Message);
		}
	}

